        )
    if rank == world_size - 1:
        recv_bottom_buf.copy_(
            _make_boundary_halo(
                x,
                recv_top_buf if world_size > 1 else None,
                height_halo_size=height_halo_size,
                is_top=False,
                mode=height_pad_mode,
            )
        )

