        torch.concat([recv_top_buf, x, recv_bottom_buf], dim=-2),
        recv_top_buf,
        recv_bottom_buf,
    )


def _make_boundary_halo(
    x: torch.Tensor,
    neighbor: torch.Tensor | None,
    *,
    height_halo_size: int,
    is_top: bool,
    mode: str,
) -> torch.Tensor:
    if mode == "zeros":
