    timestep: Optional[torch.Tensor],
    additional_t_cond: Optional[torch.Tensor],
    hidden_states: torch.Tensor,
) -> Optional[_QwenModulationCacheKey]:
    """Build the key shared by the two serial CFG forwards at one timestep."""
    if (
