# SPDX-License-Identifier: Apache-2.0

from __future__ import annotations

import dataclasses

LANE = 128


def pad_to(n: int, m: int) -> int:
    return -(-n // m) * m


@dataclasses.dataclass(frozen=True)
class KernelLayout:
    spec: object
    tp: int

    @property
    def vocab_padded(self) -> int:
        return pad_to(self.spec.vocab_size, self.tp * LANE)

    def small_rows(self) -> int:
        """Height of the per-layer bf16 slab, in rows of hidden_size values."""
        from sglang_tpu.glm_flash_megakernel.build import slab_plan

        return slab_plan(self.spec, self.spec.hidden_size)["_rows"][0]

snippets.sglang_tpu/graph_runner/gemma4_vision_tp:
# SPDX-License-Identifier: Apache-2.0
"""Gemma4 vision encoder runner + policy for TPU ``torch.compile``.

Gemma4 gets its own runner rather than reusing ``ViTTpuCompileRunner``: patches
arrive batched with per-patch ``(x, y)`` ids instead of packed behind
``cu_seqlens``, and it pools by ``pooling_kernel_size`` instead of a spatial
merger. The bucket/padding lifecycle still comes from ``VisionTpuCompilePolicy``.
"""

from __future__ import annotations

import logging
from typing import Any

import torch
import torch.nn.functional as F
from msgspec import Struct

from sglang_tpu.envs import envs
from sglang_tpu.graph_runner.vit_tpu_compile_runner import (
    VisionPaddingContext,
    VisionTpuCompilePolicy,
)

logger = logging.getLogger(__name__)

# Rungs this encoder warms when the env override is unset. Each costs one
# compile; the gap between them is the padding a small image pays. A guess,
# not a measurement.
_NUM_PATCH_BUCKETS = 6


class Gemma4VisionRunContext(Struct, frozen=True):
    """Threaded from ``prepare_call`` to ``unpad_outputs``."""

    padding: VisionPaddingContext


class Gemma4VisionTpuCompileRunner:
    """Eager until the policy installs the compiled boundary over ``forward``."""

    def __init__(self, encoder: Any) -> None:
        self.encoder = encoder
        self.owner = encoder

    @property
    def pooling_window(self) -> int:
        """Patches per pooled token; every bucket must be a whole number of these."""
        return self.encoder.pooling_kernel_size**2

    def forward(
        self, pixel_values: torch.Tensor, pixel_position_ids: torch.Tensor
    ) -> tuple[torch.Tensor, torch.Tensor]:
        # [batch, patches_bucket, patch_pixels] and [batch, patches_bucket, 2],
        # position id -1 marking padding; out is (pooled, pooler_mask).
        return self.encoder.forward(pixel_values, pixel_position_ids)

    def run(
        self, pixel_values: torch.Tensor, pixel_position_ids: torch.Tensor
    ) -> tuple[torch.Tensor, torch.Tensor]:
        """Entry point used until the policy installs its padded ``run``."""
        return self.forward(pixel_values, pixel_position_ids)


class Gemma4VisionTpuCompilePolicy(VisionTpuCompilePolicy):
    """Patch-count ladder and padded call seam for the Gemma4 vision encoder."""

    def __init__(
        self,
        encoder: Any | None = None,
        *,
        name: str = "gemma4_vision_encoder",
        **kwargs: Any,
    ) -> None:
        super().__init__(encoder, name=name, **kwargs)
        self._warned_oversize: set[int] = set()

    def _runner_ready_for_compile(self, runner: Any) -> bool:
        return isinstance(runner, Gemma4VisionTpuCompileRunner)

    def _install_run_adapter(self, runner: Any) -> None:
        def _run(
            pixel_values: torch.Tensor, pixel_position_ids: torch.Tensor
        ) -> tuple[torch.Tensor, torch.Tensor]:
            return self.run(pixel_values, pixel_position_ids)

        runner.run = _run

    def _pooling_window(self) -> int:
        return self._resolve_runner().pooling_window

    def compute_patch_buckets(self) -> list[int]:
        window = self._pooling_window()
        if envs.SGLANG_TPU_VIT_PRECOMPILE_SIZES.is_set():
            # Set but empty => () => warms nothing, i.e. precompile disabled.
            buckets = sorted(
                {int(x) for x in envs.SGLANG_TPU_VIT_PRECOMPILE_SIZES.get()}
            )
            for bucket in buckets:
                if bucket <= 0 or bucket % window:
                    raise ValueError(
                        "SGLANG_TPU_VIT_PRECOMPILE_SIZES entries must be positive "
                        f"multiples of the pooling window {window}; got {bucket}."
                    )
            return buckets
        max_patches = (
            envs.SGLANG_TPU_VIT_MAX_PRECOMPILE_PATCHES.get() // window * window
        )
        num_buckets = envs.SGLANG_TPU_VIT_NUM_PRECOMPILE_BUCKETS.get()
        if num_buckets is None:
            num_buckets = _NUM_PATCH_BUCKETS
        elif num_buckets <= 0:
            raise ValueError(
                "SGLANG_TPU_VIT_NUM_PRECOMPILE_BUCKETS must be positive; got "
                f"{num_buckets}. Set SGLANG_TPU_VIT_PRECOMPILE_SIZES to an empty "
                "value to disable precompile instead."
            )
        step = max(window, max_patches // num_buckets // window * window)
        buckets = list(range(step, max_patches + 1, step))
        if buckets and buckets[-1] != max_patches:
            buckets.append(max_patches)
        return buckets

    def make_warmup_inputs(self, patch_count: int) -> tuple[torch.Tensor, ...]:
        encoder = self._resolve_runner().encoder
        param = next(encoder.parameters())
        patch_pixels = encoder.patch_embedder.input_proj.weight.shape[-1]
        pixel_values = torch.zeros(
            1, patch_count, patch_pixels, device=param.device, dtype=param.dtype
        )
        # Exercise the padding path: mark the tail as padding, as a real call would.
        position_ids = torch.zeros(
            1, patch_count, 2, device=param.device, dtype=torch.int32
        )
        if patch_count > 1:
            position_ids[0, -1] = -1
        return (pixel_values, position_ids)

    def prepare_call(
        self, pixel_values: torch.Tensor, pixel_position_ids: torch.Tensor
    ) -> tuple[tuple[torch.Tensor, ...], Gemma4VisionRunContext]:
        seq_len = pixel_values.shape[-2]
        bucket_len = self._bucket_for(seq_len)
        padded = bucket_len is not None and bucket_len > seq_len

        if padded:
            pad = bucket_len - seq_len
            pixel_values = F.pad(pixel_values, (0, 0, 0, pad))
            # -1 is the tower's own padding marker: it drives both the attention
            # mask and the pooler mask, so padded patches change no output.
            pixel_position_ids = F.pad(pixel_position_ids, (0, 0, 0, pad), value=-1)

        ctx = Gemma4VisionRunContext(
            padding=VisionPaddingContext(
                real_seq_len=seq_len,
                bucket_len=bucket_len,
                padded=padded,
                merge_sq=self._pooling_window(),
            )
        )
        return (pixel_values, pixel_position_ids), ctx

    def unpad_outputs(
        self, result: tuple[torch.Tensor, torch.Tensor], ctx: Gemma4VisionRunContext
    ) -> tuple[torch.Tensor, torch.Tensor]:
        pooled, pooler_mask = result
        if ctx.padding.padded:
            real_pooled_len = ctx.padding.real_seq_len // ctx.padding.merge_sq
            pooled = pooled[:, :real_pooled_len]
            pooler_mask = pooler_mask[:, :real_pooled_len]
        # Stays on device: the projector runs next with device weights.
        return pooled, pooler_mask

    def run(
        self, pixel_values: torch.Tensor, pixel_position_ids: torch.Tensor
    ) -> tuple[torch.Tensor, torch.Tensor]:
        seq_len = pixel_values.shape[-2]
        if self._bucket_for(seq_len) is None and self.eager_fn is not None:
            # Past the top bucket, and recompiling is not allowed once warmup
            # has finished (fail_on_recompile), so run this image uncompiled.
            if seq_len not in self._warned_oversize:
                self._warned_oversize.add(seq_len)
                buckets = self.resolve_patch_buckets()
                logger.warning(
                    "Gemma4VisionTpuCompilePolicy: patch count %d exceeds the "
                    "largest precompiled bucket %s; running this image eagerly. "
                    "Add a bucket to SGLANG_TPU_VIT_PRECOMPILE_SIZES or raise "
                    "SGLANG_TPU_VIT_MAX_PRECOMPILE_PATCHES.",
                    seq_len,
                    buckets[-1] if buckets else None,
                )
            with torch.no_grad():
                return self.eager_fn(pixel_values, pixel_position_ids)
        return super().run(pixel_values, pixel_position_ids)

snippets.sglang_tpu/hooks/experimental_spec.py:
"""Narrow hook adapters for the experimental host-padded spec path.

Why: filter/merge and H2D staging must be intercepted before device operations,
not repaired afterward. All non-experimental calls delegate unchanged.
kimi_spec_defaults: core refuses speculation for Kimi hybrid (KDA) targets on
TPU and otherwise pins GPU verify/draft backends; the experimental worker
serves DSPARK on the TPU KDA checkpoint verify, so it skips both.
materialize_future_map: the live FutureMap's lazy torch.empty buffers would fuse
into their first store, compiling at whatever shape the first batch has.
budget_pd_hidden_pool: the KV budget does not know the PD hidden pool built after
it (SGLANG_TPU_PD_DECODE_DRAFT_PREFILL); add its bytes per token to the default
configurator's cell size and reject the configurators it does not size.
reject_overlong_pd_draft_prompt: the decode's draft prompt pass takes a whole
prompt in one extend bucket; abort a longer one at admission, before its KV transfer.
Upstream seam issue: not filed (local prototype). Before proposing upstream,
replace these hooks with agreed factories/overrides for the extracted operations.
Remove when: the experiment is removed or those upstream seams are available.
"""

from __future__ import annotations

from collections.abc import Callable

import torch

from sglang.srt.managers.overlap_utils import FutureMap
from sglang.srt.managers.schedule_batch import ScheduleBatch
from sglang.srt.runtime_context import get_disagg, get_spec
from sglang.srt.speculative.spec_info import SpecInput, SpeculativeAlgorithm
from sglang_tpu._logging import get_logger
from sglang_tpu.experimental import (
    experimental_spec_enabled,
    get_host_batch_padder,
    is_experimental_chain,
    is_experimental_spec,
    is_experimental_spec_worker,
    uses_host_batch,
)
from sglang_tpu.experimental.speculative.draft_info import HostPaddedDraftInput

logger = get_logger(__name__)


def initialize_host_batch(result, *args, **kwargs):
    # Every batch of a process a TpuSpecWorker serves is host padded, whatever the algorithm.
    padder = get_host_batch_padder()
    if padder is not None:
        # Only decode relays through FutureMap; a PD prefill (PP runs it
        # without overlap) never decodes.
        if not result.enable_overlap and get_disagg().disaggregation_mode != "prefill":
            raise ValueError(
                "The experimental TPU spec worker requires overlap scheduling "
                "outside --disaggregation-mode prefill"
            )
        result.host_pad_bs = padder
    return result


def copy_host_batch(result, batch):
    if uses_host_batch(batch):
        result.host_pad_bs = batch.host_pad_bs
    return result


def sampling_from_batch(
    original, cls, batch, vocab_size, *, sampling_params_on_cpu=False
):
    if uses_host_batch(batch):
        from sglang_tpu.experimental.sampling.sampling_batch_info import (
            HostPaddedSamplingInfo,
        )

        cls = HostPaddedSamplingInfo
    return original(
        cls, batch, vocab_size, sampling_params_on_cpu=sampling_params_on_cpu
    )


def _relays_rows(batch) -> bool:
    """Whether FutureMap owns batch's rows; a non-overlap PD prefill keeps core's."""
    return uses_host_batch(batch) and batch.enable_overlap


def _rebuild_relay_rows(batch):
    assert batch.enable_overlap and not batch.spec_algorithm.is_none()
    assert batch.input_ids is None
    batch.req_pool_indices = batch.req_pool_indices_cpu.to(
        batch.device, non_blocking=True
    )
    # FutureMap resolves these before forward; direct compile ignores orig_seq_lens.
    batch.seq_lens = None
    batch.orig_seq_lens = None


def filter_model_inputs(original, batch, keep_indices, keep_indices_device):
    if not _relays_rows(batch):
        return original(batch, keep_indices, keep_indices_device)
    _rebuild_relay_rows(batch)


def merge_model_inputs(original, batch, other):
    assert uses_host_batch(batch) == uses_host_batch(other)
    if not _relays_rows(batch):
        return original(batch, other)
    assert other.input_ids is None
    _rebuild_relay_rows(batch)


def _draft_state_on_host(spec_info: SpecInput | None) -> bool:
    from sglang.srt.speculative.dflash_info_v2 import DFlashDraftInputV2
    from sglang.srt.speculative.eagle_info import EagleDraftInput

    return (
        isinstance(spec_info, (EagleDraftInput, DFlashDraftInputV2))
        and spec_info.bonus_tokens is not None
        and spec_info.bonus_tokens.device.type == "cpu"
    )


def filter_spec_input(original, batch, keep_indices, keep_indices_device):
    if not _relays_rows(batch):
        if _draft_state_on_host(batch.spec_info):
            # A PP PD prefill keeps the relayed draft state on host; index it there.
            keep_indices_device = torch.tensor(keep_indices, dtype=torch.int64)
        return original(batch, keep_indices, keep_indices_device)
    from sglang_tpu.experimental.speculative.draft_info import HostPaddedDraftInput

    assert isinstance(batch.spec_info, HostPaddedDraftInput)
    batch.spec_info.filter_batch(
        new_indices=keep_indices_device,
        new_indices_cpu=keep_indices,
        future_indices=batch.req_pool_indices,
    )


def merge_spec_input(original, batch, other):
    if not _relays_rows(batch):
        return original(batch, other)
    from sglang_tpu.experimental.speculative.draft_info import HostPaddedDraftInput

    assert isinstance(batch.spec_info, HostPaddedDraftInput)
    batch.spec_info.merge_batch(other.spec_info, future_indices=batch.req_pool_indices)


def prepare_spec_decode(original, batch):
    # Core routes only DFlash-family decode prep to the stateful draft input;
    # every TpuSpecWorker input is a HostPaddedDraftInput, which reserves KV and
    # plans the bucketed verify window.
    if not uses_host_batch(batch) or batch.spec_algorithm.is_dflash_family():
        return original(batch)
    from sglang_tpu.experimental.speculative.draft_info import HostPaddedDraftInput

    assert isinstance(batch.spec_info, HostPaddedDraftInput)
    batch.spec_info.prepare_for_decode(batch)


SeedBuilder = Callable[[ScheduleBatch, torch.Tensor, FutureMap], SpecInput]


def build_disagg_eagle_input(
    original: SeedBuilder,
    batch: ScheduleBatch,
    last_tokens_tensor: torch.Tensor,
    future_map: FutureMap,
) -> SpecInput:
    # Core stacks the seed on device at the live bs, one compile per bs. The chain
    # worker (MTP, EAGLE3) keeps the draft hidden in its carry table instead.
    if not uses_host_batch(batch):
        return original(batch, last_tokens_tensor, future_map)
    from sglang_tpu.experimental import get_pd_carry_seeder, pd_decode_draft_prefill
    from sglang_tpu.experimental.speculative.chain_info import (
        HostPaddedChainDraftInput,
    )
    from sglang_tpu.experimental.speculative.pd_draft_prefill import (
        get_pd_draft_prefiller,
    )

    assert is_experimental_chain(batch.spec_algorithm), batch.spec_algorithm
    if any(req.output_dsa_topk_indices is not None for req in batch.reqs):
        raise NotImplementedError("TpuChainSpecWorker does not support DSA PD seeds.")
    if pd_decode_draft_prefill():
        # The draft prompt pass writes the draft KV and the carry.
        get_pd_draft_prefiller()(batch)
    else:
        get_pd_carry_seeder()(
            batch.req_pool_indices_cpu,
            torch.stack([req.hidden_states_tensor for req in batch.reqs]),
        )
    draft_input = HostPaddedChainDraftInput(
        bonus_tokens=last_tokens_tensor,
        new_seq_lens=batch.seq_lens.to(torch.int64),
    )
    return _relay_disagg_seed(batch, draft_input, future_map)


def build_disagg_block_input(
    original: SeedBuilder,
    batch: ScheduleBatch,
    last_tokens_tensor: torch.Tensor,
    future_map: FutureMap,
) -> SpecInput:
    # DFlash/DSpark seed only the bonus token; the draft context KV arrives with
    # the PD transfer of the draft pool, or comes from the shipped hidden rows.
    if not uses_host_batch(batch):
        return original(batch, last_tokens_tensor, future_map)
    from sglang_tpu.experimental import pd_decode_draft_prefill
    from sglang_tpu.experimental.speculative.block_info import (
        HostPaddedBlockDraftInput,
    )
    from sglang_tpu.experimental.speculative.pd_draft_prefill import (
        get_pd_draft_prefiller,
    )

    if pd_decode_draft_prefill():
        # The prefill shipped target hidden rows; project them into the draft KV here.
        get_pd_draft_prefiller()(batch)
    draft_input = HostPaddedBlockDraftInput(
        bonus_tokens=last_tokens_tensor,
        new_seq_lens=batch.seq_lens.to(torch.int64),
    )
    return _relay_disagg_seed(batch, draft_input, future_map)


def _relay_disagg_seed(
    batch: ScheduleBatch, draft_input: HostPaddedDraftInput, future_map: FutureMap
) -> HostPaddedDraftInput:
    """Publish and stash the seed by pool row, as core's PD seed builders do."""
    from sglang.srt.managers.overlap_utils import RelayPayload

    assert batch.enable_overlap
    _reset_pd_checkpoints(batch)
    draft_input.future_indices = batch.req_pool_indices
    future_map.publish(draft_input.future_indices, batch.seq_lens)
    future_map.stash(
        draft_input.future_indices, RelayPayload.from_draft_input(draft_input)
    )
    return draft_input


def _reset_pd_checkpoints(batch: ScheduleBatch) -> None:
    # The transferred GDN state lands in each slot's own row, but a reused decode
    # slot keeps its previous read offset; prebuilt skips extend's reset.
    from sglang.srt.mem_cache.memory_pool import HybridReqToTokenPool
    from sglang_tpu.mamba_pool import TpuMambaPool

    pool = batch.req_to_token_pool
    if not isinstance(pool, HybridReqToTokenPool):
        return
    mamba_pool = pool.mamba_pool
    assert isinstance(mamba_pool, TpuMambaPool), type(mamba_pool)
    if mamba_pool.checkpoint_read_offsets is not None:
        mamba_pool.clear_slots(
            torch.stack([req.kv.mamba_pool_idx.reshape(()) for req in batch.reqs])
        )


def materialize_future_map(
    result: FutureMap, algorithm: SpeculativeAlgorithm, *args, **kwargs
) -> FutureMap:
    # A torch.empty buffer stays lazy and fuses into its first store, one program
    # per first-batch shape; an uploaded buffer is concrete.
    if algorithm.is_none():
        return result
    from sglang_tpu.compilation.recompilation_checker import (
        snapshot_recompilation_baseline,
    )

    result.output_tokens_buf = _uploaded_zeros_like(result.output_tokens_buf)
    result.new_seq_lens_buf = _uploaded_zeros_like(result.new_seq_lens_buf)
    # The map is built after the scheduler's warmup baseline.
    torch.accelerator.synchronize()
    snapshot_recompilation_baseline()
    return result


def _uploaded_zeros_like(buf: torch.Tensor) -> torch.Tensor:
    return torch.zeros(buf.shape, dtype=buf.dtype).to(buf.device)


def stage_prefill_tokens(original, batch):
    if not uses_host_batch(batch):
        return original(batch)
    assert batch.mix_running_indices is None, (
        "Host-padded spec does not support mixed chunks"
    )
    return batch.prefill_input_ids_cpu


def alloc_extend(
    original,
    tree_cache,
    prefix_lens,
    prefix_lens_cpu,
    seq_lens,
    seq_lens_cpu,
    last_loc,
    extend_num_tokens,
    req_pool_indices=None,
    batch=None,
    out_cache_loc_host=None,
    return_host=False,
):
    if uses_host_batch(batch):
        return_host = True
        if out_cache_loc_host is None:
            out_cache_loc_host = torch.empty((extend_num_tokens,), dtype=torch.int32)
    return original(
        tree_cache=tree_cache,
        prefix_lens=prefix_lens,
        prefix_lens_cpu=prefix_lens_cpu,
        seq_lens=seq_lens,
