    top_k = info.uniform_top_k
    if (
        top_k is None
        or top_k <= 1
        or info.is_any_greedy
        or info.sampling_seed is not None
        or not info.need_top_k_sampling
        or info.need_top_p_sampling
        or info.need_min_p_sampling
